<?php declare(strict_types=1); namespace Tests\Unit\Review; use App\Domain\Review\Enum\ReviewRating;use App\Interface\Http\Review\ReviewRequestFactory;use PHPUnit\Framework\TestCase;use Slim\Psr7\Factory\ServerRequestFactory;use Slim\Psr7\Factory\StreamFactory;final class ReviewRequestFactoryTest extends TestCase {public function testBuildsRatingInputFromValidatedJson():void{$request=(new ServerRequestFactory())->createServerRequest('POST','/v1/review/sessions/session/cards/card/reviews')->withBody((new StreamFactory())->createStream('{"rating":"GOOD"}'));$dto=(new ReviewRequestFactory())->rate($request,'session','card');self::assertSame('session',$dto->sessionId);self::assertSame('card',$dto->flashcardId);self::assertSame(ReviewRating::GOOD,$dto->rating);}public function testRejectsMalformedRatingPayload():void{$this->expectException(\InvalidArgumentException::class);$request=(new ServerRequestFactory())->createServerRequest('POST','/')->withBody((new StreamFactory())->createStream('{'));(new ReviewRequestFactory())->rate($request,'session','card');}public function testLimitsPaginationToOneHundred():void{$this->expectException(\InvalidArgumentException::class);$request=(new ServerRequestFactory())->createServerRequest('GET','/')->withQueryParams(['per_page'=>'101']);(new ReviewRequestFactory())->perPage($request);}}
